// A store's long work on a thread of its own (D-274): its progress in bytes, a wait for the
// next change, a cancel, and its result.
//
// # Job
//
// Each language builds its own idioms on these methods: a stream of progress, and the
// awaited result cancelling the job when the caller's task is cancelled.
//
// Its methods may run on any goroutine at once. Close frees it at once; otherwise it is freed
// once unreachable. A method called after Close fails with CodeInvalidArgument, or panics
// when it returns no error.
type Job struct {
	mu      sync.RWMutex
	raw     uintptr // the C handle; 0 once closed
	cleanup runtime.Cleanup
}

func newJob(raw uintptr) *Job {
	h := &Job{raw: raw}
	h.cleanup = runtime.AddCleanup(h, rawJobFree, raw)
	return h
}

// Close frees the job once no method is running on it. Closing it again does
// nothing.
func (h *Job) Close() {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.raw != 0 {
		h.cleanup.Stop()
		rawJobFree(h.raw)
		h.raw = 0
	}
}

// acquire holds the job open until release and returns its C handle (0 when
// closed or nil, which the library refuses with CodeInvalidArgument).
func (h *Job) acquire() uintptr {
	if h == nil {
		return 0
	}
	h.mu.RLock()
	return h.raw
}

func (h *Job) release() {
	if h != nil {
		h.mu.RUnlock()
	}
}

// Waits until the progress moves past `seq` (from `seq`), the job ends, or
// `timeout_ms` passes; returns the sequence then. Polling with the last one returned
// sees every change.
//
// # Blocks
//
// Until the job moves or ends: call it off a UI thread, or use the language's
// asynchronous form.
func (h *Job) WaitProgress(seq uint64, timeoutMs uint32) uint64 {
	handle := h.acquire()
	defer h.release()
	var out uint64
	var msg tgBytes
	status := rawJobWaitProgress(handle, seq, timeoutMs, &out, &msg)
	if status != 0 {
		panic(newError(status, &msg, "tg_job_wait_progress"))
	}
	return out
}

// The progress's sequence number: it moves on with every change.
func (h *Job) Seq() uint64 {
	handle := h.acquire()
	defer h.release()
	var out uint64
	var msg tgBytes
	status := rawJobSeq(handle, &out, &msg)
	if status != 0 {
		panic(newError(status, &msg, "tg_job_seq"))
	}
	return out
}

// Bytes received so far.
func (h *Job) DoneBytes() uint64 {
	handle := h.acquire()
	defer h.release()
	var out uint64
	var msg tgBytes
	status := rawJobDoneBytes(handle, &out, &msg)
	if status != 0 {
		panic(newError(status, &msg, "tg_job_done_bytes"))
	}
	return out
}

// Bytes expected, from the catalog's sizes: never below the bytes received, and equal
// to them once the job ends.
func (h *Job) TotalBytes() uint64 {
	handle := h.acquire()
	defer h.release()
	var out uint64
	var msg tgBytes
	status := rawJobTotalBytes(handle, &out, &msg)
	if status != 0 {
		panic(newError(status, &msg, "tg_job_total_bytes"))
	}
	return out
}

// Whether the job has ended (done, failed or cancelled); its result is then ready.
func (h *Job) IsEnded() bool {
	handle := h.acquire()
	defer h.release()
	var out bool
	var msg tgBytes
	status := rawJobIsEnded(handle, &out, &msg)
	if status != 0 {
		panic(newError(status, &msg, "tg_job_is_ended"))
	}
	return out
}

// Asks the job to stop at its next request or chunk; it then fails with
// `ErrorCode::Cancelled` and leaves the store as it was.
func (h *Job) Cancel() {
	handle := h.acquire()
	defer h.release()
	var msg tgBytes
	status := rawJobCancel(handle, &msg)
	if status != 0 {
		panic(newError(status, &msg, "tg_job_cancel"))
	}
}

// The job's result, waiting for it to end.
//
// # Errors
//
// The job's: `ErrorCode::Network`, `ErrorCode::Refused`, `ErrorCode::Cancelled`,
// or `ErrorCode::Io` and `ErrorCode::Corrupt` for an engine's packs.
//
// # Blocks
//
// Until the job moves or ends: call it off a UI thread, or use the language's
// asynchronous form.
func (h *Job) Result() ([]byte, error) {
	handle := h.acquire()
	defer h.release()
	var out tgBytes
	var msg tgBytes
	status := rawJobResult(handle, &out, &msg)
	if status != 0 {
		return nil, newError(status, &msg, "tg_job_result")
	}
	return takeBytes(out), nil
}

// Progress yields the job's progress now and each time it moves, until it ends, ctx is
// done or the loop stops:
//
//	for p := range job.Progress(ctx) {
//		fmt.Println(p.Done, "of", p.Total)
//	}
func (h *Job) Progress(ctx context.Context) iter.Seq[JobProgress] {
	return func(yield func(JobProgress) bool) {
		seq := h.Seq()
		last := JobProgress{Done: h.DoneBytes(), Total: h.TotalBytes()}
		if !yield(last) {
			return
		}
		for !h.IsEnded() {
			if ctx.Err() != nil {
				return
			}
			if next := h.WaitProgress(seq, 250); next != seq {
				seq = next
				last = JobProgress{Done: h.DoneBytes(), Total: h.TotalBytes()}
				if !yield(last) {
					return
				}
			}
		}
		if end := (JobProgress{Done: h.DoneBytes(), Total: h.TotalBytes()}); end != last {
			yield(end)
		}
	}
}

// Wait waits for the job's result, cancelling it if ctx is done first (the result is then
// CodeCancelled).
func (h *Job) Wait(ctx context.Context) ([]byte, error) {
	stop := context.AfterFunc(ctx, func() {
		handle := h.acquire()
		defer h.release()
		if handle != 0 {
			var msg tgBytes
			_ = rawJobCancel(handle, &msg)
		}
	})
	defer stop()
	return h.Result()
}

// JobProgress is a job's bytes done and bytes expected.
type JobProgress struct {
	Done  uint64
	Total uint64
}
